<script setup lang="ts">
import type {VaultSource} from '~~/shared/types/sharing'
import type {ScopedCredential} from '~~/shared/utils/vault-sources'
const props=defineProps<{sources:VaultSource[]}>()
const emit=defineEmits<{edit:[entry:ScopedCredential]}>()
const {paymentEntry,group,currency,search,statusFilter,groups,currencyOptions,statusOptions,from,to,chartCurrency,chartOptions,tab,validRange,planned,payments,planTotals,paidTotals,monthly,distribution,amountLabel,dateLabel,stamp}=useSubscriptionFinances(props)
</script>
<template><section class="subscription-finances">
 <SubscriptionFilters v-model:group="group" v-model:currency="currency" v-model:search="search" v-model:status="statusFilter" :groups="groups" :currency-options="currencyOptions" :status-options="statusOptions"/>
 <div class="finance-date-filters"><UFormField label="С"><UInput v-model="from" type="date" aria-label="Начало финансового периода"/></UFormField><UFormField label="По"><UInput v-model="to" type="date" aria-label="Конец финансового периода"/></UFormField><UFormField label="Валюта графиков"><USelect v-model="chartCurrency" :items="chartOptions" aria-label="Валюта графиков"/></UFormField></div>
 <UAlert v-if="!validRange" class="mb-4" color="warning" title="Выберите корректный период длительностью до 10 лет."/>
 <div class="finance-tabs" role="tablist" aria-label="Финансовые записи"><button role="tab" :aria-selected="tab==='plan'" @click="tab='plan'">План списаний · {{ planned.length }}</button><button role="tab" :aria-selected="tab==='history'" @click="tab='history'">История оплат · {{ payments.length }}</button><button role="tab" :aria-selected="tab==='report'" @click="tab='report'">Отчёт</button><button role="tab" :aria-selected="tab==='reports'" @click="tab='reports'">История отчётов</button></div>
 <FinanceReports v-if="tab==='report'||tab==='reports'" :mode="tab" :sources="sources" :from="from" :to="to" :group="group" :currency="currency" :search="search" :valid-range="validRange"/>
 <template v-else>
 <div class="finance-summary-grid"><article><span>Плановые списания за период</span><strong v-for="total in planTotals" :key="total.currency">{{ amountLabel(total.amount,total.currency) }}</strong><p v-if="!planTotals.length">Нет списаний</p></article><article><span>Отмеченные оплаты за период</span><strong v-for="total in paidTotals" :key="total.currency">{{ amountLabel(total.amount,total.currency) }}</strong><p v-if="!paidTotals.length">Оплаты пока не отмечены</p></article><article><span>Плановых списаний</span><strong>{{ planned.length }}</strong><p>Валюта не конвертируется, суммы считаются отдельно.</p></article></div>
 <FinanceChart @open="entry=>emit('edit',entry)" :monthly="monthly" :distribution="distribution" :currency="chartCurrency"/>

 <div class="finance-table-scroll"><table v-if="tab==='plan'" class="finance-table"><thead><tr><th>Дата</th><th>Сервис / подписка</th><th>Хранилище</th><th>Сумма</th><th>Тип</th></tr></thead><tbody><tr v-for="event in planned" :key="event.key"><td>{{ dateLabel(event.date) }}</td><td><button class="subscription-service" @click="emit('edit',event.row.entry)">{{ event.row.entry.title }}</button><small>{{ event.row.field.label }}</small></td><td>{{ (event.row.entry.vaultNames??[event.row.entry.vaultName]).join(' · ') }}</td><td>{{ amountLabel(event.amount,event.currency) }}</td><td>{{ event.forecast?'Прогноз продления':'Ближайшее списание' }}</td></tr></tbody></table><table v-else class="finance-table"><thead><tr><th>Дата оплаты</th><th>Сервис / подписка</th><th>Хранилище</th><th>Сумма</th><th>Оплаченный период</th></tr></thead><tbody><tr v-for="payment in payments" :key="`${payment.vaultId}/${payment.id}`"><td>{{ stamp(payment.paidAt) }}</td><td><button v-if="paymentEntry(payment)" type="button" class="subscription-service" @click="emit('edit',paymentEntry(payment)!)">{{ payment.service }}</button><span v-else>{{ payment.service }}</span><small>{{ payment.label }}</small></td><td>{{ payment.vaultNames.join(' · ') }}</td><td>{{ amountLabel(payment.amount,payment.currency) }}</td><td>{{ dateLabel(payment.periodFrom) }} — {{ dateLabel(payment.periodUntil) }}</td></tr></tbody></table></div>
 <p v-if="tab==='plan'&&!planned.length||tab==='history'&&!payments.length" class="subscription-empty">Записей с выбранными фильтрами нет.</p>
 <p class="subscription-note">История включает оплаты кнопки «Отметить оплату» и прошлые списания, внесённые в разделе «История списаний». Там можно добавлять, редактировать и удалять записи. Изменение стоимости не меняет прошлые суммы. Фильтр срока применяется к прогнозу, история фильтруется по дате оплаты, хранилищу, валюте и поиску. Уже оплаченные периоды исключены из плана. Будущие списания рассчитаны по текущей цене и периоду автопродления. Общая подписка учитывается один раз; в распределении — в первом доступном хранилище. Сайт не списывает деньги.</p>
 </template>
 </section></template>
